import java.util.*;
import java.io.*;

public class VariantTwo {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        int[] diff = new int[n];
        int idx = 0;
        int evenCount = a[0] % 2 == 0 ? 1 : 0;
        int oddCount = a[0] % 2 == 1 ? 1 : 0;
        for (int i = 1; i < n; i++) {
            if (evenCount == oddCount) {
                diff[idx++] = Math.abs(a[i] - a[i - 1]);
            }
            if (a[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        Arrays.sort(diff, 0, idx);
        long total = 0;
        int count = 0;
        for (int i = 0; i < idx; i++) {
            if (diff[i] + total <= b) {
                count++;
                total += diff[i];
            }
        }
        System.out.println(count);
        sc.close();
    }
}
